//! The person-name bloom filter and stopwords, as generated by
//! `packages/sensored/scripts/generate-bloom-filter.ts` into `data.rs` and
//! `bloom.bin`. The bits are used in place; nothing is decoded.
//!
//! Hashing must match the script bit for bit: FNV-1a and DJB2 over UTF-16
//! code units, double hashing `(h1 + i * h2) % m`, exact in TS doubles.

use super::data::{BLOOM_BITS, BLOOM_K, BLOOM_M, STOPWORDS};

const _: () = assert!(BLOOM_BITS.len() == BLOOM_M.div_ceil(8) as usize);

const FNV_OFFSET_BASIS: u32 = 0x811c_9dc5;
const FNV_PRIME: u32 = 0x0100_0193;
const DJB2_SEED: u32 = 5381;

/// Whether the lowercased `word` may be a name.
///
/// The filter holds lowercase ASCII names, so ASCII lowercasing equals JS
/// `toLowerCase` here. Common Latin letters with diacritics are folded to
/// ASCII first (`Müller` looks up `muller`); a word with any other non-ASCII
/// character is not a name.
pub fn has_name(word: &str) -> bool {
    if !word.chars().all(|ch| fold(ch).is_some()) {
        return false;
    }

    let units = word
        .chars()
        .filter_map(fold)
        .flat_map(|folded| folded.bytes());
    let (h1, h2) = hashes(units);
    let m = u64::from(BLOOM_M);

    (0..u64::from(BLOOM_K)).all(|i| {
        let position = (u64::from(h1) + i * u64::from(h2)) % m;
        let bit = 1 << (position % 8);

        // `position < m`, so the index is in bounds (asserted above).
        BLOOM_BITS[(position / 8) as usize] & bit != 0
    })
}

/// Whether the lowercased `word` is a stopword.
pub fn is_stopword(word: &str) -> bool {
    contains_folded(STOPWORDS, word)
}

/// Whether the sorted lowercase `list` holds `word`, ASCII-lowercased.
pub fn contains_folded(list: &[&str], word: &str) -> bool {
    list.binary_search_by(|entry| {
        entry
            .bytes()
            .cmp(word.bytes().map(|byte| byte.to_ascii_lowercase()))
    })
    .is_ok()
}

/// One character, lowercased and folded to ASCII; `None` if it has no fold.
fn fold(ch: char) -> Option<&'static str> {
    if ch.is_ascii() {
        let index = ch.to_ascii_lowercase() as usize;

        return ASCII.get(index..=index);
    }

    let folded = match ch {
        'à'..='å' | 'À'..='Å' | 'ā' | 'Ā' | 'ą' | 'Ą' => "a",
        'æ' | 'Æ' => "ae",
        'ç' | 'Ç' | 'ć' | 'Ć' | 'č' | 'Č' => "c",
        'ď' | 'Ď' | 'đ' | 'Đ' => "d",
        'è'..='ë' | 'È'..='Ë' | 'ē' | 'Ē' | 'ę' | 'Ę' | 'ě' | 'Ě' => "e",
        'ğ' | 'Ğ' => "g",
        'ì'..='ï' | 'Ì'..='Ï' | 'ī' | 'Ī' | 'ı' | 'İ' => "i",
        'ł' | 'Ł' => "l",
        'ñ' | 'Ñ' | 'ń' | 'Ń' | 'ň' | 'Ň' => "n",
        'ò'..='ö' | 'Ò'..='Ö' | 'ø' | 'Ø' | 'ō' | 'Ō' | 'ő' | 'Ő' => "o",
        'œ' | 'Œ' => "oe",
        'ř' | 'Ř' => "r",
        'ß' => "ss",
        'ś' | 'Ś' | 'š' | 'Š' | 'ş' | 'Ş' => "s",
        'ť' | 'Ť' | 'ţ' | 'Ţ' => "t",
        'ù'..='ü' | 'Ù'..='Ü' | 'ū' | 'Ū' | 'ů' | 'Ů' | 'ű' | 'Ű' => "u",
        'ý' | 'Ý' | 'ÿ' => "y",
        'ź' | 'Ź' | 'ż' | 'Ż' | 'ž' | 'Ž' => "z",
        _ => return None,
    };

    Some(folded)
}

/// Every ASCII character, so a folded ASCII character can be a `&'static str`.
const ASCII: &str = concat!(
    "\0\x01\x02\x03\x04\x05\x06\x07\x08\t\n\x0B\x0C\r\x0E\x0F",
    "\x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\x1A\x1B\x1C\x1D\x1E\x1F",
    " !\"#$%&'()*+,-./0123456789:;<=>?",
    "@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_",
    "`abcdefghijklmnopqrstuvwxyz{|}~\x7F",
);

const _: () = assert!(ASCII.len() == 128);

/// `(fnv1a32, djb2)` over UTF-16 units given as bytes (ASCII only).
fn hashes(units: impl Iterator<Item = u8>) -> (u32, u32) {
    units.fold((FNV_OFFSET_BASIS, DJB2_SEED), |(fnv, djb2), unit| {
        let unit = u32::from(unit);

        (
            (fnv ^ unit).wrapping_mul(FNV_PRIME),
            // JS: `((hash << 5) + hash + c) >>> 0`, i.e. `hash * 33 + c` mod 2^32.
            djb2.wrapping_mul(33).wrapping_add(unit),
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hash::fnv1a32;

    #[test]
    fn fnv_matches_core_hash() {
        for word in ["", "a", "john", "smith", "elizabeth"] {
            assert_eq!(hashes(word.bytes()).0, fnv1a32(word), "{word}");
        }
    }

    /// Expected values come from the TS `djb2`.
    #[test]
    fn djb2_matches_ts_reference() {
        assert_eq!(hashes("".bytes()).1, 5381);
        assert_eq!(hashes("john".bytes()).1, 2_090_407_348);
        assert_eq!(hashes("bartholomew-alexander".bytes()).1, 121_259_498);
    }

    /// Expected values come from the TS `BloomFilter.has`.
    #[test]
    fn bloom_matches_ts_reference() {
        let names = [
            "john",
            "smith",
            "jane",
            "elizabeth",
            "harrington",
            "maria",
            "garcia",
        ];
        let common = [
            "new", "york", "apple", "monday", "quick", "street", "london",
        ];
        let absent = [
            "doe",
            "inc",
            "the",
            "zzqx",
            "patient",
            "report",
            "xylophone",
        ];

        for word in names.iter().chain(&common) {
            assert!(has_name(word), "{word}");
        }

        for word in absent {
            assert!(!has_name(word), "{word}");
        }
    }

    #[test]
    fn lowercases_before_lookup() {
        assert_eq!(has_name("John"), has_name("john"));
        assert!(is_stopword("Monday"));
        assert!(!is_stopword("John"));
    }

    #[test]
    fn folds_latin_diacritics() {
        assert!(has_name("Müller"));
        assert_eq!(has_name("José"), has_name("jose"));
        assert_eq!(has_name("Søren"), has_name("soren"));
        assert!(!has_name("Иван"));
    }

    #[test]
    fn stopwords_are_sorted_and_unique() {
        assert!(STOPWORDS.windows(2).all(|pair| pair[0] < pair[1]));
    }
}
